'use client';

import { useState } from 'react';
import { LoginForm } from '@/components/auth/LoginForm';
import { SignupForm } from '@/components/auth/SignupForm';

export default function AuthPage() {
  const [isSignUp, setIsSignUp] = useState(false);

  return (
    <main className="relative min-h-screen w-full flex items-center justify-center p-4 bg-slate-900 overflow-hidden font-sans">
      <div 
        className="absolute inset-0 bg-cover bg-center bg-no-repeat scale-105 filter brightness-75"
        style={{ backgroundImage: `url('/images/hero-bg.jpg')` }}
      />
      <div className="absolute inset-0 bg-black/40 backdrop-blur-[2px]" />

      <div className="relative z-10 w-full max-w-md">
        {isSignUp ? (
          <SignupForm onSwitchToLogin={() => setIsSignUp(false)} />
        ) : (
          <LoginForm onSwitchToSignup={() => setIsSignUp(true)} />
        )}
      </div>
    </main>
  );
}